insert into public.ideas (id,code,title,category,summary,description,price,capital_min,capital_max,payback_months,margin_percent,difficulty,includes,featured) values
('specialty-coffee-cart','F-014','عربة قهوة مختصة','أغذية ومشروبات','نقطة بيع متنقلة قرب الجامعات والمكاتب، بتكاليف تشغيل منخفضة وهامش ربح عالٍ.','مشروع قهوة مختصة على عربة أو كشك صغير، يستهدف الطلاب والموظفين في ساعات الذروة الصباحية. يعتمد على قائمة قصيرة ومنتقاة، وتجربة سريعة، وحضور قوي على وسائل التواصل.',149,15000,25000,8,55,'سهل',array['قائمة المعدات والموردين','تكلفة الكوب وتسعير القائمة','خطة اختيار الموقع','خطة إطلاق أول 30 يوم']::text[],true),
('home-bakery-brand','F-021','علامة مخبوزات منزلية','أغذية ومشروبات','تحويل مطبخ البيت إلى علامة تجارية تبيع عبر إنستغرام والطلبات المسبقة.','مشروع مخبوزات يبدأ من البيت بالطلب المسبق، مع هوية بصرية واضحة وتغليف مميز. يتوسع لاحقاً إلى التوريد للمقاهي والمناسبات.',119,3000,7000,4,45,'سهل',array['حساب تكلفة كل منتج','نموذج الطلب المسبق','أفكار تغليف وهوية','خطة محتوى إنستغرام']::text[],true),
('ecommerce-niche-store','F-033','متجر إلكتروني متخصص','تجارة إلكترونية','متجر يركّز على فئة واحدة من المنتجات بدل كل شيء، مع شحن محلي.','اختيار فئة منتجات ضيقة (مثل مستلزمات الحيوانات الأليفة أو أدوات القهوة المنزلية)، والاستيراد بكميات صغيرة، والبيع عبر متجر إلكتروني وإعلانات ممولة مدروسة.',199,9000,22000,10,35,'متوسط',array['طريقة اختيار الفئة','قائمة موردين','ميزانية الإعلانات','حاسبة التسعير والشحن']::text[],true),
('kids-activity-studio','F-040','استوديو أنشطة للأطفال','تعليم وخدمات','ورشات فن وعلوم للأطفال بنظام الاشتراك الشهري.','مساحة صغيرة تقدم أنشطة أسبوعية للأطفال بنظام الاشتراك، مع حفلات أعياد ميلاد وورشات صيفية كمصادر دخل إضافية.',199,22000,45000,14,40,'متوسط',array['نموذج الاشتراكات','تجهيز المساحة','برنامج أنشطة 3 أشهر','خطة التسويق للأهالي']::text[],false),
('car-detailing-mobile','F-052','خدمة تلميع سيارات متنقلة','خدمات','نخدم العميل في موقعه بالحجز المسبق، بدون محل ولا إيجار.','خدمة غسيل وتلميع سيارات تصل إلى بيت العميل أو مكتبه، بالحجز عبر واتساب، مع باقات شهرية للشركات.',149,11000,20000,7,50,'سهل',array['قائمة المعدات والمواد','تسعير الباقات','نظام الحجز','عقود الشركات']::text[],false),
('cloud-kitchen','F-067','مطبخ سحابي','أغذية ومشروبات','مطبخ للتوصيل فقط يشغّل أكثر من علامة تجارية من نفس المكان.','مطبخ بدون صالة، يعمل عبر تطبيقات التوصيل، ويمكنه تشغيل 2–3 علامات تجارية بقوائم مختلفة لزيادة الطلبات من نفس التكاليف الثابتة.',279,55000,110000,18,30,'متقدم',array['دراسة جدوى كاملة','تصميم المطبخ','هندسة القائمة','اتفاقيات تطبيقات التوصيل']::text[],false)
insert into public.workshops (id,title,summary,description,date,duration_hours,mode,location,price,seats,seats_taken,trainer,agenda) values
('from-idea-to-plan','من الفكرة إلى الخطة','يوم عملي تخرج منه بخطة مشروع من صفحة واحدة وأرقام أولية واضحة.','ورشة تطبيقية نشتغل فيها على فكرتك أنت: نحدد العميل، نحسب التكاليف، ونبني خطة إطلاق بسيطة قابلة للتنفيذ.','2026-11-14T10:00:00',5,'حضوري','يُحدد لاحقاً',120,20,13,'فريق Hura',array['اختبار الفكرة بسرعة','حساب التكاليف ونقطة التعادل','خطة أول 90 يوم','عرض الخطط وتقييمها']::text[]),
('pricing-that-profits','تسعير يحقق ربح','كيف تسعّر منتجك أو خدمتك بدون ما تخسر أو تطفّش العميل.','جلسة أونلاين مكثفة عن حساب التكلفة الحقيقية، وهامش الربح، والتسعير حسب السوق، مع أمثلة من مشاريع صغيرة حقيقية.','2026-11-28T18:00:00',2,'أونلاين','Zoom',50,60,22,'فريق Hura',array['التكلفة الحقيقية','طرق التسعير الثلاث','العروض والخصومات بذكاء']::text[]),
('instagram-sales','إنستغرام كقناة بيع','حوّل حسابك من معرض صور إلى مصدر طلبات ثابت.','ورشة عن بناء محتوى يبيع، وتحويل المتابعين إلى عملاء، وإدارة الطلبات عبر الرسائل وواتساب.','2026-12-12T17:00:00',3,'أونلاين','Zoom',70,50,9,'فريق Hura',array['هوية الحساب','محتوى يبيع','من الرسالة إلى الطلب']::text[])
